def get_row(lst, x):
    coordinates = []
    for i in range(len(lst)):
        row = lst[i]
        for j in range(len(row)):
            if row[j] == x:
            coordinates.append((i, j))

    # Sort by rows ascending, then by columns descending
    coordinates.sort(key=lambda c: (c[0], -c[1]))

    return coordinates
```

